<div class="result-box"><div class="result-grid"><div class="metric"><span>Seller-allocated cost</span><strong id="seller">—</strong></div><div class="metric"><span>Buyer-allocated cost</span><strong id="buyer">—</strong></div><div class="metric"><span>Unallocated / optional</span><strong id="other">—</strong></div></div><div id="note" class="helper" style="margin-top:12px"></div></div>
<script>
(()=>{const $=id=>document.getElementById(id);const comps=[['origin','Origin handling / pickup',200],['export','Export clearance',75],['main','Main carriage',1200],['insurance','Cargo insurance',80],['import','Import clearance',100],['duty','Import duties / taxes',350],['dest','Destination handling',150],['unload','Unloading at named destination',100],['final','Final delivery',250]];const preset={EXW:{},FCA:{origin:'seller',export:'seller',main:'buyer'},FAS:{origin:'seller',export:'seller',main:'buyer'},FOB:{origin:'seller',export:'seller',main:'buyer'},CFR:{origin:'seller',export:'seller',main:'seller'},CIF:{origin:'seller',export:'seller',main:'seller',insurance:'seller'},CPT:{origin:'seller',export:'seller',main:'seller'},CIP:{origin:'seller',export:'seller',main:'seller',insurance:'seller'},DAP:{origin:'seller',export:'seller',main:'seller',dest:'seller',final:'seller'},DPU:{origin:'seller',export:'seller',main:'seller',dest:'seller',unload:'seller',final:'seller'},DDP:{origin:'seller',export:'seller',main:'seller',import:'seller',duty:'seller',dest:'seller',final:'seller'}};function render(){const tb=$('rows');tb.innerHTML='';comps.forEach(([id,label,v])=>{const tr=document.createElement('tr');tr.innerHTML=`<td>${label}</td><td><input id="amt-${id}" type="number" min="0" step="any" value="${v}" style="max-width:130px"></td><td><select id="pay-${id}"><option value="seller">Seller</option><option value="buyer">Buyer</option><option value="unallocated">Unallocated / contract-specific</option></select></td>`;tb.appendChild(tr);tr.querySelector('input').addEventListener('input',calc);tr.querySelector('select').addEventListener('change',calc)});apply()}function apply(){const t=$('term').value,p=preset[t]||{};comps.forEach(([id])=>{$('pay-'+id).value=p[id]||((['import','duty','dest','unload','final'].includes(id)||t==='EXW')?'buyer':'unallocated')});if(!['CIF','CIP'].includes(t))$('pay-insurance').value='unallocated';calc()}function calc(){let s=0,b=0,u=0;comps.forEach(([id])=>{const a=parseFloat($('amt-'+id).value)||0,p=$('pay-'+id).value;if(p==='seller')s+=a;else if(p==='buyer')b+=a;else u+=a});const c=$('currency').value||'';$('seller').textContent=c+s.toLocaleString(undefined,{maximumFractionDigits:2});$('buyer').textContent=c+b.toLocaleString(undefined,{maximumFractionDigits:2});$('other').textContent=c+u.toLocaleString(undefined,{maximumFractionDigits:2});$('note').textContent='Preset is a planning aid only. Incoterms allocate obligations, costs and risk at defined delivery points; named place/port, carriage contracts, terminal charges, insurance scope and local law can change the commercial total. Review the sale contract.'}$('term').addEventListener('change',apply);$('currency').addEventListener('input',calc);$('preset').onclick=apply;render()})();
</script>
